/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import { loadFont, loadFont as loadInter } from "@remotion/google-fonts/Inter";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useMemo,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractivitySchema,
  interpolate,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate as culoriInterpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

const toRgb = converter("rgb");

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    culoriInterpolate(
      [resolveColorString(a), resolveColorString(b)],
      "oklch",
    )(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * Everything below is measured frame by frame off a 1920x1080, 30fps reference.
 * Times are frames, lengths are em unless a comment says otherwise.
 */

/** A word's slide in, as a fraction of `travel`, one entry per frame of its own clock. */
const ENTRY = [
  1, 0.64, 0.484, 0.374, 0.29, 0.224, 0.172, 0.128, 0.094, 0.066, 0.044, 0.028,
  0.016, 0.008, 0.002, 0,
] as const;

/**
 * Brightness against time, relative to the moment the highlight's centre reaches
 * a point of the line: [frames, level], where 1 is full ink. One curve explains
 * every word of the reference to 0.8% of full scale.
 */
const SWEEP: readonly (readonly [number, number])[] = [
  [-50, 0.255],
  [-49, 0.271],
  [-45, 0.377],
  [-42, 0.437],
  [-39, 0.467],
  [-31, 0.525],
  [-25, 0.587],
  [-12, 0.806],
  [-5, 0.966],
  [-3, 0.99],
  [0, 1],
  [4, 0.995],
  [6, 0.974],
  [13, 0.81],
  [26, 0.588],
  [33, 0.517],
  [43, 0.462],
  [51, 0.365],
];

/** Default mark: a rounded bolt in a `ICON_BOX` viewBox. */
const BOLT =
  "M54.13 2.15A5.78 5.78 0 0 1 64.00 7.96L47.41 48.65A1.03 1.03 0 0 0 48.36 50.07L78.20 50.31A4.41 4.41 0 0 1 81.63 57.46L30.83 121.75A5.39 5.39 0 0 1 21.55 116.54L37.50 73.40L6.96 72.69A4.58 4.58 0 0 1 3.50 65.25Z";
const ICON_BOX: [number, number] = [83.07, 123.79];

/**
 * Spec Sweep — one centred line that arrives word by word and then gets read
 * out by a highlight. Every word slides in on its own clock, a soft band of
 * brightness travels along the line, and an icon charges up from the bottom.
 *
 * The defaults are measured off a 1920x1080 reference: it is a single curve
 * through time (`SWEEP`), reached at each point of the line by its distance from
 * the start plus that word's entry delay, so copy of any length rides the same
 * band.
 */

const { fontFamily: INTER } = loadFont("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

export type SpecSegmentRole = "lead" | "icon" | "accent" | "muted";

export interface SpecSegment {
  /** The words. Split on spaces; each word enters on its own. Unused by `icon`. */
  text?: string;
  /**
   * `lead` rides the highlight and falls back to grey behind it. `accent` stays
   * lit once the highlight has reached it. `muted` never rises past `mutedLevel`.
   * `icon` draws the `icon` path, charged with `accentColor`.
   */
  role?: SpecSegmentRole;
}

export interface SpecSweepProps {
  segments?: SpecSegment[];
  /** SVG path data of the icon, drawn in an `iconBox` viewBox. */
  icon?: string;
  /** viewBox width and height of `icon`. */
  iconBox?: [number, number];
  /** Icon height, in em. */
  iconSize?: number;
  /** Icon colour once charged. Defaults to `theme.primary`. */
  accentColor?: string;
  /** Opacity of the icon before the charge reaches it. */
  iconDim?: number;
  /** Lighter inner edge of the icon, px on a 1920 stage. 0 turns it off. */
  iconRim?: number;
  /** Colour of that edge. Defaults to `accentColor` towards white. */
  iconRimColor?: string;
  /** Frames from the icon's entry to the start of its charge, and the charge's length. */
  chargeDelay?: number;
  chargeFrames?: number;
  /** A family from `fonts.ts`, or a CSS family you have loaded yourself. */
  fontFamily?: string;
  /** Type size, px on a 1920 stage. Long copy shrinks from here to fit. */
  fontSize?: number;
  fontWeight?: number;
  /** How far a word slides in, em. */
  travel?: number;
  /** Frames between one word's entry and the next. Compressed on long copy. */
  stagger?: number;
  /** Frames the highlight takes to cross the line. */
  sweepFrames?: number;
  /** Level `muted` words are capped at. */
  mutedLevel?: number;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  speed?: number;
}

/** Widest the line may get, as a fraction of the stage: a word still sliding in stays on it. */
const MAX_LINE = 0.85;
/** The last word has landed by this frame, however long the copy. */
const LAST_ENTRY = 14;
/** Frame the highlight's centre leaves the start of the line. */
const SWEEP_START = 1.476;
/** Frames a word is ahead of the highlight at the very start of its slide. */
const SWEEP_LEAD = 6.093;
/** The text baseline sits this far below the stage centre, em. */
const BASELINE = 0.258;
/** Spacing of the sampled gradient stops, px on a 1920 stage. */
const STOP_EVERY = 8;

const chargeEase = Easing.bezier(0.166, 0.092, 0.279, 1);

const held = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const ENTRY_AT = ENTRY.map((_, i) => i);
const SWEEP_AT = SWEEP.map(([at]) => at);
const SWEEP_LEVEL = SWEEP.map(([, level]) => level);

/** The fraction of `travel` a word has left, `age` frames after it entered. */
const entryOffset = (age: number) =>
  interpolate(age, ENTRY_AT, [...ENTRY], held);

/** Level of a word at `t` frames past the highlight's centre. */
const sweepLevel = (role: SpecSegmentRole, t: number, mutedLevel = 0.6) => {
  if (role === "accent" && t > 0) return 1;
  const level = interpolate(t, SWEEP_AT, SWEEP_LEVEL, held);
  return role === "muted" ? Math.min(level, mutedLevel) : level;
};

export interface LineItem {
  role: SpecSegmentRole;
  text: string;
  /** Left edge from the start of the line, and advance. px. */
  x: number;
  w: number;
}

/** Splits segments into words and lays them on one line. */
const layoutLine = (
  segments: SpecSegment[],
  measure: (text: string) => number,
  iconWidth: number,
) => {
  const space = measure(" ");
  const items: LineItem[] = [];
  let x = 0;
  const push = (role: SpecSegmentRole, text: string, w: number) => {
    items.push({ role, text, x, w });
    x += w + space;
  };
  for (const s of segments) {
    if (s.role === "icon") push("icon", "", iconWidth);
    else
      for (const word of (s.text ?? "").split(/\s+/).filter(Boolean))
        push(s.role ?? "lead", word, measure(word));
  }
  return { items, width: Math.max(0, x - space) };
};

const makeMeasure = (font: string, size: number) => {
  const ctx =
    typeof document === "undefined"
      ? null
      : document.createElement("canvas").getContext("2d");
  if (!ctx) return (text: string) => text.length * 0.55 * size;
  ctx.font = font;
  return (text: string) => ctx.measureText(text).width;
};

const DEFAULT_SEGMENTS: SpecSegment[] = [
  { text: "Ship", role: "lead" },
  { role: "icon" },
  { text: "a launch film", role: "accent" },
  { text: "in", role: "muted" },
  { text: "20 minutes", role: "accent" },
];

const SpecSweepScene = ({
  segments = DEFAULT_SEGMENTS,
  icon = BOLT,
  iconBox = ICON_BOX,
  iconSize = 1.452,
  accentColor,
  iconDim = 0.39,
  iconRim = 1.47,
  iconRimColor,
  chargeDelay = 11.47,
  chargeFrames = 30,
  fontFamily,
  fontSize = 85.15,
  fontWeight = 500,
  travel = 1.466,
  stagger = 2,
  sweepFrames = 54,
  mutedLevel = 0.6,
  theme,
  mode = "dark",
  speed = 1,
}: SpecSweepProps) => {
  const f = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const id = useId().replace(/:/g, "");
  const family = resolveFont(fontFamily ?? t.fontFamily) ?? INTER;
  const stage = Math.min(width / 1920, height / 1080);

  // A width measured before the face lands is a width for the fallback, so the
  // layout waits on it; a render holds its first frame until that has re-rendered.
  const [fontTick, setFontTick] = useState(0);
  const [handle] = useState(() =>
    getRemotionEnvironment().isRendering
      ? delayRender("spec-sweep: loading the face")
      : null,
  );
  const fontSpec = `${fontWeight} 100px ${family}`;
  useEffect(() => {
    let alive = true;
    document.fonts
      .load(fontSpec)
      .catch(() => [])
      .then(() => {
        if (alive) setFontTick((n) => n + 1);
      });
    return () => {
      alive = false;
    };
  }, [fontSpec]);
  useEffect(() => {
    if (fontTick > 0 && handle != null) continueRender(handle);
  }, [fontTick, handle]);

  const line = useMemo(() => {
    void fontTick;
    const place = (size: number) =>
      layoutLine(
        segments,
        makeMeasure(`${fontWeight} ${size}px ${family}`, size),
        (size * iconSize * iconBox[0]) / iconBox[1],
      );
    const size = fontSize * stage;
    const first = place(size);
    const fit = Math.min(1, (MAX_LINE * width) / Math.max(1, first.width));
    const fitted = fit < 1 ? place(size * fit) : first;
    return { ...fitted, size: size * fit, left: (width - fitted.width) / 2 };
  }, [
    fontTick,
    segments,
    fontWeight,
    family,
    iconSize,
    iconBox,
    fontSize,
    stage,
    width,
  ]);

  const { items, size, left } = line;
  const step = Math.min(stagger, LAST_ENTRY / Math.max(1, items.length - 1));
  const rate = line.width / sweepFrames; // px per frame
  const baseline = height / 2 + BASELINE * size;
  const accent = accentColor ?? t.primary;
  const rimColor = iconRimColor ?? mixOklch(accent, "#ffffff", 0.3);
  const ink = t.foreground;

  const iconH = size * iconSize;
  const iconScale = iconH / iconBox[1];

  return (
    <AbsoluteFill showInTimeline={false} style={{ background: t.background }}>
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", inset: 0, overflow: "hidden" }}
      >
        {items.map((item, i) => {
          const age = f - step * i;
          if (age < 0) return null;
          const off = entryOffset(age);
          const x = left + item.x + off * travel * size;

          if (item.role === "icon") {
            const charge = chargeEase(
              Math.min(1, Math.max(0, (age - chargeDelay) / chargeFrames)),
            );
            const level = iconBox[1] * (1.006 - 1.018 * charge);
            const clip = `${id}c${i}`;
            const shape = (fill: string, rim: string) => (
              <>
                <path d={icon} fill={fill} />
                {iconRim > 0 && (
                  <path
                    d={icon}
                    fill="none"
                    stroke={rim}
                    strokeWidth={(2 * iconRim * stage) / iconScale}
                    clipPath={`url(#${clip})`}
                  />
                )}
              </>
            );
            return (
              <g
                key={`${item.x}`}
                transform={`translate(${x} ${height / 2 - iconH / 2}) scale(${iconScale})`}
              >
                <clipPath id={clip}>
                  <path d={icon} />
                </clipPath>
                <clipPath id={`${clip}a`}>
                  <rect x={-9e3} y={-9e3} width={18e3} height={9e3 + level} />
                </clipPath>
                <clipPath id={`${clip}b`}>
                  <rect x={-9e3} y={level} width={18e3} height={9e3} />
                </clipPath>
                <g clipPath={`url(#${clip}a)`} opacity={iconDim}>
                  {shape(accent, rimColor)}
                </g>
                <g clipPath={`url(#${clip}b)`}>{shape(accent, rimColor)}</g>
              </g>
            );
          }

          // The highlight reaches each point of the word at its own moment, so the
          // word is painted with a gradient sampled from that one curve.
          const grad = `${id}g${i}`;
          const from = age + SWEEP_LEAD * off - SWEEP_START - item.x / rate;
          const n = Math.max(2, Math.ceil(item.w / (STOP_EVERY * stage)));
          const stops = Array.from({ length: n + 1 }, (_, k) => {
            const u = k / n;
            return (
              <stop
                key={u}
                offset={u}
                stopColor={ink}
                stopOpacity={sweepLevel(
                  item.role,
                  from - (u * item.w) / rate,
                  mutedLevel,
                )}
              />
            );
          });
          return (
            <g key={`${item.x}`}>
              <linearGradient
                id={grad}
                gradientUnits="userSpaceOnUse"
                x1={x}
                x2={x + item.w}
                y1={0}
                y2={0}
              >
                {stops}
              </linearGradient>
              <text
                x={x}
                y={baseline}
                fill={`url(#${grad})`}
                style={{
                  fontFamily: family,
                  fontWeight,
                  fontSize: size,
                  textRendering: "geometricPrecision",
                }}
              >
                {item.text}
              </text>
            </g>
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type SpecSweepElementProps = Omit<
  ComponentProps<typeof SpecSweepScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const SpecSweepDefaults = {
  accentColor: "#3577e0",
  fontSize: 85.15,
  mode: "dark",
  speed: 1,
} satisfies Partial<SpecSweepElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const SpecSweepSchema = {
  accentColor: {
    type: "color",
    default: "#3577e0",
    description: "Icon",
    keyframable: false,
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  fontSize: {
    type: "number",
    default: 85.15,
    min: 40,
    max: 140,
    step: 1,
    description: "Type size",
    hiddenFromList: false,
    keyframable: false,
  },
  mode: {
    type: "enum",
    default: "dark",
    description: "Mode",
    variants: { light: {}, dark: {} },
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function SpecSweepFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const SpecSweepInner = forwardRef<HTMLDivElement, SpecSweepElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...SpecSweepDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <SpecSweepFade>
            <SpecSweepScene key={key} {...rest} />
          </SpecSweepFade>
        </div>
      </Sequence>
    );
  },
);

export const SpecSweep = Interactive.withSchema({
  Component: SpecSweepInner,
  componentName: "<SpecSweep>",
  schema: SpecSweepSchema,
  wrapInSequence: true,
});
